CREATE TABLE `balance_hidrico_manual` (
  `fecha` date NOT NULL,
  `turno` tinyint NOT NULL,
  `carrotanques_m3` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'm³ recibidos de carrotanques ese turno',
  `kg_tela` decimal(10,2) DEFAULT NULL COMMENT 'kg de tela procesados en tintorería',
  `und_efectivas` decimal(10,2) DEFAULT NULL COMMENT 'unidades efectivas procesadas en lavandería',
  `m_tela` decimal(10,2) DEFAULT NULL COMMENT 'metros de tela procesados en rotativa',
  `mulas_funza_m3` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT 'm³ recibidos de mulas de Funza',
  `cargado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`fecha`,`turno`),
  CONSTRAINT `chk_turno_bh` CHECK ((`turno` in (1,2,3)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Entradas manuales de producción para el balance hídrico (no derivan de contadores)';
