DROP TABLE IF EXISTS `contadores_lectura`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `contadores_lectura` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `fecha` date NOT NULL,
  `turno` tinyint unsigned NOT NULL COMMENT '1=10PM-6AM | 2=6AM-2PM | 3=2PM-10PM',
  `hora_lectura` time NOT NULL COMMENT '22:00=T1 | 06:00=T2 | 14:00=T3',
  `entrada_ap_principal_6in` bigint unsigned DEFAULT NULL,
  `entrada_ap_fria_lavanderia_4in` bigint unsigned DEFAULT NULL,
  `entrada_ap_lab_lavanderia` bigint unsigned DEFAULT NULL,
  `entrada_ap_fria_tintoreria_4in` bigint unsigned DEFAULT NULL,
  `entrada_ap_rotativa_3in` bigint unsigned DEFAULT NULL,
  `entrada_ap_tintoreria_6in` bigint unsigned DEFAULT NULL COMMENT '100% nulo en 2026',
  `entrada_ap_ptar2_acueducto` bigint unsigned DEFAULT NULL,
  `entrada_ap_puerta2_acueducto` bigint unsigned DEFAULT NULL,
  `entrada_ap_puerta4_acueducto` bigint unsigned DEFAULT NULL,
  `entrada_ap_puerta5_acueducto` bigint unsigned DEFAULT NULL,
  `entrada_ap_puerta6_acueducto` bigint unsigned DEFAULT NULL COMMENT '100% nulo en 2026',
  `entrada_ap_puerta7_acueducto` bigint unsigned DEFAULT NULL,
  `entrada_ap_caldera_acueducto` bigint unsigned DEFAULT NULL,
  `entrada_ap_quimicos` bigint unsigned DEFAULT NULL,
  `entrada_ap_lavanderia_acueducto` bigint unsigned DEFAULT NULL,
  `entrada_ap_zona_lodos_acueducto` bigint unsigned DEFAULT NULL,
  `entrada_medidor_rojo_tintoreria_4in` bigint unsigned DEFAULT NULL,
  `entrada_medidor_rojo_lavanderia_4in` bigint unsigned DEFAULT NULL,
  `rama` bigint unsigned DEFAULT NULL,
  `abridora_1` bigint unsigned DEFAULT NULL,
  `abridora_2` bigint unsigned DEFAULT NULL,
  `agua_caliente_tintoreria` bigint unsigned DEFAULT NULL,
  `medidor_prueba_agua_caliente` bigint unsigned DEFAULT NULL,
  `tanque_reuso_2in` bigint unsigned DEFAULT NULL,
  `ptar` bigint unsigned DEFAULT NULL,
  `envio_th` bigint unsigned DEFAULT NULL,
  `entrada_ro1` bigint unsigned DEFAULT NULL,
  `salida_ro1` bigint unsigned DEFAULT NULL,
  `entrada_ro2` bigint unsigned DEFAULT NULL,
  `salida_ro2` bigint unsigned DEFAULT NULL,
  `mbr1` bigint unsigned DEFAULT NULL,
  `mbr2` bigint unsigned DEFAULT NULL,
  `ingreso_uf_ptap` bigint unsigned DEFAULT NULL,
  `salida_uf_ptap` bigint unsigned DEFAULT NULL,
  `medidor_verde_retorno` bigint unsigned DEFAULT NULL,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `observaciones` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `usuario` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `equipo` text COLLATE utf8mb4_unicode_ci,
  `gem_prueba` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fecha_turno` (`fecha`,`turno`),
  KEY `idx_fecha` (`fecha`),
  CONSTRAINT `chk_hora_turno` CHECK ((((`turno` = 1) and (`hora_lectura` = '22:00:00')) or ((`turno` = 2) and (`hora_lectura` = '06:00:00')) or ((`turno` = 3) and (`hora_lectura` = '14:00:00')))),
  CONSTRAINT `chk_turno` CHECK ((`turno` in (1,2,3)))
) ENGINE=InnoDB AUTO_INCREMENT=1285 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Lecturas acumuladas (odometro) de 35 contadores por fecha+turno — PTAR 2 2026';
/*!40101 SET character_set_client = @saved_cs_client */;

