DROP TABLE IF EXISTS `medicion_calidad`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `medicion_calidad` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `fecha` date NOT NULL,
  `turno` tinyint NOT NULL,
  `parametro_id` int NOT NULL,
  `unidad_id` int NOT NULL,
  `valor` decimal(18,6) DEFAULT NULL,
  `observacion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `usuario` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `metodo` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `no_aplica` tinyint(1) DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `equipo` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_mc` (`fecha`,`turno`,`parametro_id`,`unidad_id`),
  UNIQUE KEY `uq_medicion` (`fecha`,`turno`,`parametro_id`,`unidad_id`),
  KEY `idx_mc_fecha` (`fecha`),
  KEY `idx_mc_param` (`parametro_id`),
  KEY `idx_mc_unidad` (`unidad_id`),
  CONSTRAINT `fk_mc_param` FOREIGN KEY (`parametro_id`) REFERENCES `parametro_calidad` (`id`),
  CONSTRAINT `fk_mc_unidad` FOREIGN KEY (`unidad_id`) REFERENCES `unidad_tratamiento` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=81289 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
