--
-- Table structure for table `medidor`
--

DROP TABLE IF EXISTS `medidor`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `medidor` (
  `id` tinyint unsigned NOT NULL AUTO_INCREMENT,
  `codigo_columna` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nombre de campo en contadores_lectura',
  `nombre_completo` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nombre original del Excel',
  `area` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Area o sistema al que pertenece',
  `diametro` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Diametro de la linea (6", 4", 3", 1/2"...)',
  `tipo_agua` enum('potable','reuso','proceso','retorno','permeado_ro','caliente','otro') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'potable',
  `col_excel` tinyint unsigned NOT NULL COMMENT 'Indice columna Excel 1-based (C=3..AK=37)',
  `unidad` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'm3',
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `notas` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_medidor_columna` (`codigo_columna`),
  UNIQUE KEY `uq_medidor_col_excel` (`col_excel`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Catalogo de 35 contadores fisicos instalados en PTAR 2';
/*!40101 SET character_set_client = @saved_cs_client */;

