CREATE TABLE `operacion_gem_turno` (
  `id` int NOT NULL AUTO_INCREMENT,
  `fecha` date NOT NULL,
  `dia_mes` tinyint NOT NULL,
  `turno` tinyint NOT NULL,
  `turno_descripcion` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `diligencia_bitacora` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `final_acido_l` decimal(12,2) DEFAULT NULL,
  `final_coagulante_l` decimal(12,2) DEFAULT NULL,
  `final_decolorante_l` decimal(12,2) DEFAULT NULL,
  `final_pol_anionico_kg` decimal(12,2) DEFAULT NULL,
  `final_pol_cationico_kg` decimal(12,2) DEFAULT NULL,
  `horometro_inicial` int DEFAULT NULL,
  `caudal_total_tratado_gem_m3` decimal(12,2) DEFAULT NULL,
  `caudal_tratamiento_m3h` decimal(10,2) DEFAULT NULL,
  `consumo_acido_l` decimal(12,2) DEFAULT NULL,
  `consumo_coagulante_l` decimal(12,2) DEFAULT NULL,
  `consumo_decolorante_l` decimal(12,2) DEFAULT NULL,
  `consumo_pol_anionico_kg` decimal(12,2) DEFAULT NULL,
  `consumo_pol_cationico_kg` decimal(12,2) DEFAULT NULL,
  `kg_acido` decimal(12,4) DEFAULT NULL,
  `kg_coagulante` decimal(12,4) DEFAULT NULL,
  `kg_decolorante` decimal(12,4) DEFAULT NULL,
  `kg_pol_anionico` decimal(12,4) DEFAULT NULL,
  `kg_pol_cationico` decimal(12,4) DEFAULT NULL,
  `ppm_acido` decimal(12,4) DEFAULT NULL,
  `ppm_coagulante` decimal(12,4) DEFAULT NULL,
  `ppm_decolorante` decimal(12,4) DEFAULT NULL,
  `ppm_pol_anionico` decimal(12,4) DEFAULT NULL,
  `ppm_pol_cationico` decimal(12,4) DEFAULT NULL,
  `costo_op_acido` decimal(14,2) DEFAULT NULL,
  `costo_op_coagulante` decimal(14,2) DEFAULT NULL,
  `costo_op_decolorante` decimal(14,2) DEFAULT NULL,
  `costo_op_anionico` decimal(14,2) DEFAULT NULL,
  `costo_op_cationico` decimal(14,2) DEFAULT NULL,
  `costo_quimica_turno` decimal(14,2) DEFAULT NULL,
  `limite_indicador_m3` decimal(12,2) DEFAULT NULL,
  `pesos_por_m3` decimal(14,4) DEFAULT NULL,
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `usuario` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `equipo` text COLLATE utf8mb4_unicode_ci,
  `consumo_pol_anionico_l` decimal(12,4) DEFAULT NULL,
  `consumo_pol_cationico_l` decimal(12,4) DEFAULT NULL,
  `ingreso_coagulante_l` decimal(12,2) DEFAULT NULL,
  `trasegado_coagulante_ptap_l` decimal(12,2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_gem_fecha_turno` (`fecha`,`turno`),
  KEY `idx_gem_fecha` (`fecha`)
) ENGINE=InnoDB AUTO_INCREMENT=2233 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
