/*!50001 VIEW `lecturas_con_turno` AS select `contadores_lectura`.`id` AS `id`,`contadores_lectura`.`fecha` AS `fecha`,`contadores_lectura`.`turno` AS `turno`,(case `contadores_lectura`.`turno` when 1 then '10PM-6AM' when 2 then '6AM-2PM' when 3 then '2PM-10PM' end) AS `turno_descripcion`,`contadores_lectura`.`hora_lectura` AS `hora_lectura`,`contadores_lectura`.`entrada_ap_principal_6in` AS `entrada_ap_principal_6in`,`contadores_lectura`.`entrada_ap_fria_lavanderia_4in` AS `entrada_ap_fria_lavanderia_4in`,`contadores_lectura`.`entrada_ap_lab_lavanderia` AS `entrada_ap_lab_lavanderia`,`contadores_lectura`.`entrada_ap_fria_tintoreria_4in` AS `entrada_ap_fria_tintoreria_4in`,`contadores_lectura`.`entrada_ap_rotativa_3in` AS `entrada_ap_rotativa_3in`,`contadores_lectura`.`entrada_ap_ptar2_acueducto` AS `entrada_ap_ptar2_acueducto`,`contadores_lectura`.`entrada_ap_puerta2_acueducto` AS `entrada_ap_puerta2_acueducto`,`contadores_lectura`.`entrada_ap_puerta4_acueducto` AS `entrada_ap_puerta4_acueducto`,`contadores_lectura`.`entrada_ap_puerta5_acueducto` AS `entrada_ap_puerta5_acueducto`,`contadores_lectura`.`entrada_ap_puerta7_acueducto` AS `entrada_ap_puerta7_acueducto`,`contadores_lectura`.`entrada_ap_caldera_acueducto` AS `entrada_ap_caldera_acueducto`,`contadores_lectura`.`entrada_ap_quimicos` AS `entrada_ap_quimicos`,`contadores_lectura`.`entrada_ap_lavanderia_acueducto` AS `entrada_ap_lavanderia_acueducto`,`contadores_lectura`.`entrada_ap_zona_lodos_acueducto` AS `entrada_ap_zona_lodos_acueducto`,`contadores_lectura`.`entrada_medidor_rojo_tintoreria_4in` AS `entrada_medidor_rojo_tintoreria_4in`,`contadores_lectura`.`entrada_medidor_rojo_lavanderia_4in` AS `entrada_medidor_rojo_lavanderia_4in`,`contadores_lectura`.`rama` AS `rama`,`contadores_lectura`.`abridora_1` AS `abridora_1`,`contadores_lectura`.`abridora_2` AS `abridora_2`,`contadores_lectura`.`agua_caliente_tintoreria` AS `agua_caliente_tintoreria`,`contadores_lectura`.`medidor_prueba_agua_caliente` AS `medidor_prueba_agua_caliente`,`contadores_lectura`.`tanque_reuso_2in` AS `tanque_reuso_2in`,`contadores_lectura`.`ptar` AS `ptar`,`contadores_lectura`.`envio_th` AS `envio_th`,`contadores_lectura`.`entrada_ro1` AS `entrada_ro1`,`contadores_lectura`.`salida_ro1` AS `salida_ro1`,`contadores_lectura`.`entrada_ro2` AS `entrada_ro2`,`contadores_lectura`.`salida_ro2` AS `salida_ro2`,`contadores_lectura`.`mbr1` AS `mbr1`,`contadores_lectura`.`mbr2` AS `mbr2`,`contadores_lectura`.`ingreso_uf_ptap` AS `ingreso_uf_ptap`,`contadores_lectura`.`salida_uf_ptap` AS `salida_uf_ptap`,`contadores_lectura`.`medidor_verde_retorno` AS `medidor_verde_retorno` from `contadores_lectura` */;
