/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `v_balance_hidrico` AS with `ct` as (select `ct`.`fecha` AS `fecha`,`ct`.`turno` AS `turno`,coalesce(`ct`.`cons_ingreso_uf_ptap`,0) AS `ingreso_ptap`,coalesce(`ct`.`cons_salida_uf_ptap`,0) AS `potable_ptap`,(coalesce(`ct`.`cons_entrada_ap_principal_6in`,0) * 10) AS `contador_principal`,(coalesce(`ct`.`cons_entrada_ro1`,0) / 1000) AS `entrada_ro1`,coalesce(`ct`.`cons_salida_ro1`,0) AS `permeado_ro1`,coalesce(`ct`.`cons_entrada_ap_fria_lavanderia_4in`,0) AS `lavanderia_m3`,coalesce(`ct`.`cons_entrada_ap_rotativa_3in`,0) AS `rotativa_m3`,coalesce(`ct`.`cons_tanque_reuso_2in`,0) AS `contador_acueducto`,coalesce(`ct`.`cons_envio_th`,0) AS `envio_th`,coalesce(`ct`.`cons_mbr1`,0) AS `permeado_mbr1`,coalesce(`ct`.`cons_mbr2`,0) AS `permeado_mbr2`,coalesce(`ct`.`cons_agua_caliente_tintoreria`,0) AS `agua_caliente`,(coalesce(`ct`.`cons_medidor_verde_retorno`,0) / 1000) AS `retorno_verde`,`ct`.`rollover_detectado` AS `rollover_detectado` from `consumo_turno` `ct`), `bh` as (select `bm`.`fecha` AS `fecha`,`bm`.`turno` AS `turno`,coalesce(`bm`.`carrotanques_m3`,0) AS `carrotanques`,`bm`.`kg_tela` AS `kg_tela`,`bm`.`und_efectivas` AS `und_efectivas`,`bm`.`m_tela` AS `m_tela`,coalesce(`bm`.`mulas_funza_m3`,0) AS `mulas_funza` from `balance_hidrico_manual` `bm`), `gem` as (select `og`.`fecha` AS `fecha`,`og`.`turno` AS `turno`,`og`.`caudal_total_tratado_gem_m3` AS `consumo_gem_m3` from `operacion_gem_turno` `og`) select `ct`.`fecha` AS `fecha`,`ct`.`turno` AS `turno`,week(`ct`.`fecha`,3) AS `semana`,dayofmonth(`ct`.`fecha`) AS `dia`,`ct`.`ingreso_ptap` AS `ingreso_ptap`,`ct`.`potable_ptap` AS `potable_ptap`,coalesce(`bh`.`carrotanques`,0) AS `carrotanques_m3`,coalesce(`bh`.`mulas_funza`,0) AS `mulas_funza_m3`,`ct`.`contador_principal` AS `contador_principal`,`ct`.`entrada_ro1` AS `entrada_ro1`,`ct`.`permeado_ro1` AS `permeado_ro1`,(`ct`.`entrada_ro1` - `ct`.`permeado_ro1`) AS `rechazo_ro1`,(case when (`ct`.`entrada_ro1` > 0) then round(((`ct`.`permeado_ro1` / `ct`.`entrada_ro1`) * 100),2) else NULL end) AS `eficiencia_ro_pct`,`ct`.`permeado_mbr1` AS `permeado_mbr1`,`ct`.`permeado_mbr2` AS `permeado_mbr2`,`ct`.`agua_caliente` AS `agua_caliente`,`ct`.`retorno_verde` AS `retorno_verde`,`ct`.`envio_th` AS `envio_th`,greatest(((((`ct`.`envio_th` - `ct`.`ingreso_ptap`) - `ct`.`permeado_ro1`) - coalesce(`bh`.`carrotanques`,0)) - coalesce(`bh`.`mulas_funza`,0)),0) AS `acueducto_m3`,greatest((((`ct`.`envio_th` - `ct`.`ingreso_ptap`) + `ct`.`potable_ptap`) - coalesce(`bh`.`mulas_funza`,0)),0) AS `total_agua_limpia_m3`,`gem`.`consumo_gem_m3` AS `consumo_gem_m3`,`ct`.`lavanderia_m3` AS `lavanderia_m3`,`bh`.`und_efectivas` AS `und_efectivas`,(case when (coalesce(`bh`.`und_efectivas`,0) > 0) then round(((`ct`.`lavanderia_m3` * 1000.0) / `bh`.`und_efectivas`),2) else NULL end) AS `indicador_lav_l_und`,greatest((greatest((((`ct`.`envio_th` - `ct`.`ingreso_ptap`) + `ct`.`potable_ptap`) - coalesce(`bh`.`mulas_funza`,0)),0) - `ct`.`lavanderia_m3`),0) AS `tintoreria_m3`,`bh`.`kg_tela` AS `kg_tela`,(case when (coalesce(`bh`.`kg_tela`,0) > 0) then round(((greatest((greatest((((`ct`.`envio_th` - `ct`.`ingreso_ptap`) + `ct`.`potable_ptap`) - coalesce(`bh`.`mulas_funza`,0)),0) - `ct`.`lavanderia_m3`),0) * 1000.0) / `bh`.`kg_tela`),2) else NULL end) AS `indicador_tin_l_kg`,`ct`.`rotativa_m3` AS `rotativa_m3`,`ct`.`contador_acueducto` AS `contador_acueducto`,`bh`.`m_tela` AS `m_tela`,(case when (coalesce(`bh`.`m_tela`,0) > 0) then round(((`ct`.`rotativa_m3` * 1000.0) / `bh`.`m_tela`),2) else NULL end) AS `indicador_rot_l_m`,`ct`.`rollover_detectado` AS `rollover_detectado` from ((`ct` left join `bh` on(((`bh`.`fecha` = `ct`.`fecha`) and (`bh`.`turno` = `ct`.`turno`)))) left join `gem` on(((`gem`.`fecha` = `ct`.`fecha`) and (`gem`.`turno` = `ct`.`turno`)))) */;
