/*!50001 VIEW `v_calidad_estadisticas` AS select year(`m`.`fecha`) AS `anio`,month(`m`.`fecha`) AS `mes`,`p`.`codigo` AS `parametro_codigo`,`p`.`nombre` AS `parametro`,`p`.`unidad` AS `parametro_unidad`,`u`.`codigo` AS `unidad_codigo`,`u`.`nombre` AS `unidad`,`u`.`orden_tren` AS `orden_tren`,count(`m`.`valor`) AS `n_mediciones`,round(min(`m`.`valor`),4) AS `minimo`,round(max(`m`.`valor`),4) AS `maximo`,round(avg(`m`.`valor`),4) AS `promedio`,round(stddev_samp(`m`.`valor`),4) AS `desv_estandar`,(case when (avg(`m`.`valor`) <> 0) then round(((stddev_samp(`m`.`valor`) / avg(`m`.`valor`)) * 100),2) else NULL end) AS `cv_pct`,`p`.`limite_vertimiento_min` AS `limite_vertimiento_min`,`p`.`limite_vertimiento_max` AS `limite_vertimiento_max`,(case when ((`u`.`codigo` = 'VERTIMIENTO') and (count(`m`.`valor`) > 0)) then round(((100.0 * sum((case when (((`p`.`limite_vertimiento_min` is not null) and (`m`.`valor` < `p`.`limite_vertimiento_min`)) or ((`p`.`limite_vertimiento_max` is not null) and (`m`.`valor` > `p`.`limite_vertimiento_max`))) then 1 else 0 end))) / count(`m`.`valor`)),2) else NULL end) AS `pct_fuera_limite_vert` from ((`medicion_calidad` `m` join `parametro_calidad` `p` on((`p`.`id` = `m`.`parametro_id`))) join `unidad_tratamiento` `u` on((`u`.`id` = `m`.`unidad_id`))) where (`m`.`valor` is not null) group by year(`m`.`fecha`),month(`m`.`fecha`),`p`.`id`,`p`.`codigo`,`p`.`nombre`,`p`.`unidad`,`u`.`id`,`u`.`codigo`,`u`.`nombre`,`u`.`orden_tren`,`p`.`limite_vertimiento_min`,`p`.`limite_vertimiento_max` */;
/*!50001 SET character_set_client      = @saved_cs_client */;
/*!50001 SET character_set_results     = @saved_cs_results */;
